    "statement": "Leia o texto para responder às questões de 09 a 12.\n\nNot being able to distinguish fake news from real news \ncan have serious consequences for a person’s physical, \nemotional and financial well-being — especially for older \nadults, who in general are more financially stable and must \nmake more critical health decisions. So how good are older \nadults at detecting fake news?\n\nA new study has found that older adults are no more likely \nto believe in fake news than younger adults, with age-related \nsusceptibility to deceptive news evident only among those \ncategorized as the “oldest old.” The study was conducted \nby researchers at the University of Florida (UF) and the \nUniversity of Central Florida during the early phase of the \ncovid-19 pandemic. The research is the first to delineate the \nrole of analytical reasoning and news consumption frequency \non detection of fake news in older adults across a broad age \nrange as well as in direct comparison to young adults.\n\n“We wanted to see if there was an age difference in \ndetermining whether news is true or false,” said Didem \nPehlivanoglu, lead author and a postdoctoral researcher in \nthe Department of Psychology at UF. “We specifically wanted \nto look at this because we know that with aging most people \nshow some decline in their cognitive abilities. But we also \nknow some information processing abilities are preserved or \neven improved.”\n\n(Brooke Adams. https://news.ufl.edu, 02.05.2022. Adaptado.)\n\nDe acordo com o contexto apresentado, o título mais adequado para o texto é:",
