    "statement": "Os militares estavam contentes, especialmente os pequenos, os alferes, os tenentes e os capitães. Para a maioria, \na satisfação vinha da convicção de que iam estender sua \nautoridade sobre o pelotão e a companhia, a todo esse rebanho de civis; mas, em outros muitos havia sentimento mais \npuro. Eram os adeptos desse nefasto e hipócrita positivismo, \num pedantismo tirânico, limitado e estreito, que justificava \ntodas as violências, todos os assassínios, todas as ferocidades em nome da manutenção da ordem, condição necessária, lá diz ele, ao progresso e também ao advento do regime \nnormal.\n\n(Lima Barreto. Triste Fim de Policarpo Quaresma, 2008. Adaptado.)\n\nO excerto da obra literária, publicada originalmente em 1915, \ncritica a corrente de pensamento positivista por",
