    "number": "Questão 05",
    "subject": "Literatura",
    "detail": "Literatura — UEA 2022 Acompanhamento II",
    "difficulty": "Média",
    "statement": "Leia o capítulo CXI, “O muro”, do romance Memórias póstumas \nde Brás Cubas, de Machado de Assis, para responder às questões de 05 a 08.\n\nNão sendo meu costume dissimular ou esconder nada, \ncontarei nesta página o caso do muro. Eles estavam prestes \na embarcar. Entrando em casa de D. Plácida, vi um papelinho \ndobrado sobre a mesa; era um bilhete de Virgília; dizia que \nme esperava à noite, na chácara, sem falta. E concluía: “O \nmuro é baixo do lado do beco”.\n\nFiz um gesto de desagrado. A carta pareceu-me descomunalmente audaciosa, mal pensada e até ridícula. Não era \nsó convidar o escândalo, era convidá-lo de parceria com a \nrisota. Imaginei-me a saltar o muro, embora baixo e do lado \ndo beco; e, quando ia a galgá-lo, via-me agarrado por um pedestre de polícia, que me levava ao corpo da guarda. O muro \né baixo! E que tinha que fosse baixo? Naturalmente Virgília \nnão soube o que fez; era possível que já estivesse arrependida. Olhei para o papel, um pedaço de papel amarrotado, mas \ninflexível. Tive comichões de o rasgar, em trinta mil pedaços, \ne atirá-los ao vento, como o último despojo da minha aven\ntura; mas recuei a tempo; o amor-próprio, o vexame da fuga, \na ideia do medo... Não havia remédio senão ir.\n\n— Diga-lhe que vou.\n— Aonde? perguntou D. Plácida.\n— Onde ela disse que me espera.\n— Não me disse nada.\n— Neste papel.\nD. Plácida arregalou os olhos: — Mas esse papel, achei-o \nhoje de manhã, nesta sua gaveta, e pensei que...\n\nTive uma sensação esquisita. Reli o papel, mirei-o, remirei-o; era, na verdade, um antigo bilhete de Virgília, recebido \nno começo dos nossos amores, uma certa entrevista na chácara, que me levou efetivamente a saltar o muro, um muro \nbaixo e discreto. Guardei o papel e... Tive uma sensação \nesquisita.\n\n(Memórias póstumas de Brás Cubas, 2001.)\n\nLogo na frase inicial do seu relato, o narrador caracteriza-se \ncomo",
