    "statement": "A autora da Declaração dos direitos da mulher e da \ncidadã é Olympe de Gouges. Em 1793 ela foi guilhotinada em \nParis. E a condenação deveu-se ao fato de ela ter-se oposto \naos conhecidos revolucionários Robespierre e Marat, que a \nconsideraram mulher “desnaturada” e “perigosa demais”. Ao \nser conduzida à morte, Olympe de Gouges teria afirmado: \n“A mulher tem o direito de subir à guilhotina; ela deve ter \nigualmente o direito de subir à tribuna”.\n\n(Selvino José Assmann. “Apresentação: Declaração dos direitos\n\nda mulher e da cidadã”. Interthesis, v. 4, no 1, 2007. Adaptado.)\n\nArt. I\nA mulher nasce livre e tem os mesmos direitos do homem. As distinções sociais só podem ser baseadas no interesse comum.\n\n(Olympe de Gouges. “Declaração dos direitos da mulher e \nda cidadã”, 1791. Interhesis, vol. 4, no 1, 2007. Adaptado.)\n\nCom base nos excertos e em conhecimentos sobre a Revolução Francesa, o manifesto de Olympe de Gouges consiste em",
    "images": [],
    "alternatives": [
      "um questionamento da organização política vigente, exigindo a ocupação feminina da presidência.",
      "uma releitura da declaração redigida anteriormente, incluindo as mulheres de forma direta.",
      "uma defesa da monarquia absolutista, considerando que as mulheres eram mais valorizadas.",
      "uma escrita de novas propostas, ignorando os documentos publicados previamente.",
      "um posicionamento contra girondinos e jacobinos, abolindo a polarização partidária corrente."
    ],
    "correct": 1,
