    "statement": "A Greve de 1917 em São Paulo passou para a história \ncomo uma das maiores mobilizações da classe trabalhadora brasileira. A paralisação, comandada por sindicatos e \nassociações influenciadas por militantes anarquistas e sindi\ncalistas revolucionários, tornou-se um marco na história da \nPrimeira República, ajudando a enfraquecer as estruturas de \npoder da oligarquia dominante.\n\n(Frederico Duarte Bartz. “As greves de 1917 no Brasil:\n\nhistória e historiografia”. Estado, poder e revoluções:\n\nreflexões em um mundo em crise, 2019.)\n\nEntre os organizadores e participantes ativos da greve de \n1917, destacam-se",
