    "difficulty": "Difícil",
    "statement": "Leia um trecho da obra Infância, de Graciliano Ramos, para \nresponder às questões de 01 a 04.\n\nMergulhei numa comprida manhã de inverno. O açude \napojado, a roça verde, amarela e vermelha, os caminhos \nestreitos mudados em riachos, ficaram-me na alma. Depois \nveio a seca. Árvores pelaram-se, bichos morreram, o sol \ncresceu, bebeu as águas, e ventos mornos espalharam na \nterra queimada uma poeira cinzenta. Olhando-me por dentro, \npercebo com desgosto a segunda paisagem. Devastação, \ncalcinação. Nesta vida lenta sinto-me coagido entre duas \nsituações contraditórias — uma longa noite, um dia imenso e \nenervante, favorável à modorra. Frio e calor, trevas densas e \nclaridades ofuscantes.\n\nNaquele tempo a escuridão se ia dissipando, vagarosa. \nAcordei, reuni pedaços de pessoas e de coisas, pedaços \nde mim mesmo que boiavam no passado confuso, articulei \ntudo, criei o meu pequeno mundo incongruente. Às vezes as \npeças se deslocavam — e surgiam estranhas mudanças. Os \nobjetos se tornavam irreconhecíveis, e a humanidade, feita \nde indivíduos que me atormentavam e indivíduos que não me \natormentavam, perdia os característicos.\n\nBem e mal ainda não existiam, faltava razão para que \nnos afligissem com pancadas e gritos. Contudo as pancadas \ne os gritos figuravam na ordem dos acontecimentos, partiam \nsempre de seres determinados, como a chuva e o sol vinham \ndo céu. E o céu era terrível, e os donos da casa eram fortes. \nOra, sucedia que a minha mãe abrandava de repente e meu \npai, silencioso, explosivo, resolvia contar-me histórias. Admirava-me, aceitava a lei nova, ingênuo, admitia que a natureza \nse houvesse modificado. Fechava-se o doce parêntese — e \nisso me desorientava.\n\n(Infância, 2020.)\n\nUm traço bastante característico de Infância presente nesse \ntrecho é:",
